{"implementation":"def solve(case):
    segments = case['segments']
    n = len(segments)
    names = [seg['name'] for seg in segments]
    importances = [seg['importance'] for seg in segments]
    minimums = [seg['minimum'] for seg in segments]
    capacities = [seg['capacity'] for seg in segments]
    budget = case['budget']

    alloc = list(minimums)
    remaining = budget - sum(minimums)

    while remaining > 0:
        best_idx = -1
        best_priority = -1.0
        for i in range(n):
            if alloc[i] < capacities[i]:
                priority = importances[i] / (alloc[i] + 1)
                if priority > best_priority:
                    best_priority = priority
                    best_idx = i
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        remaining -= 1

    by_name = {names[i]: alloc[i] for i in range(n)}
    return {'allocations': alloc, 'by_name': by_name, 'total': sum(alloc)}
"}
